/*
 * mochisandbox — JS-first shim over the native realm-isolation plugin.
 *
 * Run untrusted JavaScript in an isolated realm: a fresh engine runtime +
 * context per sandbox (own atom table, own GC, own memory limit, own
 * interrupt budget). A sandbox cannot see the host's globals (process,
 * dynalib, fetch, ...). See mochi_modules/mochisandbox/README.md for the
 * native side and the enforcement table.
 *
 *   import { sandbox } from 'mochisandbox';
 *   const sb = sandbox({ budgetMs: 200, strict: true });
 *   sb.setGlobal('greeting', 'halo');
 *   const out = sb.run('greeting + " world"');   // -> '"halo world"'
 *   sb.free();
 */
import { loadNative } from '../mochinode/index.js';

let native = null;
let nativeFailure = null;
try {
    native = await loadNative('mochisandbox.dll');
} catch (error) {
    nativeFailure = error;
}

function ensure() {
    if (native) return native;
    throw new Error(
        `mochisandbox: native plugin unavailable: ${nativeFailure ? nativeFailure.message : 'not loaded'}`);
}

function jsonQuote(value) {
    return JSON.stringify(String(value));
}

/* A live sandbox: owns one native realm (runtime + context). */
export class Sandbox {
    constructor(id, opts) {
        this._id = id;
        this._opts = opts || {};
        this._freed = false;
    }
    /* Inject a primitive (string/number/bool/null) as a global in the realm. */
    setGlobal(name, value) {
        this._check();
        ensure().setGlobal(this._id, jsonQuote(name), jsonQuote(value));
    }
    /* Inject a pre-formed literal ('42', 'true', 'null', '[1,2,3]'). */
    setRawGlobal(name, literal) {
        this._check();
        ensure().setGlobal(this._id, jsonQuote(name), String(literal));
    }
    /* Deep-copy a host value into the realm as globalThis.__clone__ (JSON
       deep-copy: the host object graph is serialized and re-parsed inside the
       realm, so the realm holds its OWN copy, not a reference). Returns the
       host-side copy. Sandbox code reads the copy via `__clone__`. */
    clone(value) {
        this._check();
        return JSON.parse(ensure().clone(this._id, JSON.stringify(value)));
    }
    /* Evaluate a global script; returns JSON.stringify of the completion value. */
    run(source) {
        this._check();
        return ensure().run(this._id, String(source));
    }
    /* Run and parse the result back into a JS value on the host side. */
    eval(source) {
        return JSON.parse(this.run(source));
    }
    /* Eval an async global script, pump this realm's microtask queue, and
       return the promise state as {state:"fulfilled",value:...} or
       {state:"pending"}. A rejected promise throws here. */
    asyncEval(source) {
        return JSON.parse(ensure().runAsync(this._id, String(source)));
    }
    free() {
        if (this._freed) return;
        this._freed = true;
        try { ensure().free(this._id); } catch (e) { /* already gone */ }
    }
    get id() { return this._id; }
    _check() {
        if (this._freed) throw new Error('mochisandbox: sandbox already freed');
    }
}

/* sandbox({ budgetMs, memLimit, strict }) -> Sandbox */
export function sandbox(opts) {
    const m = ensure();
    const id = m.create(opts || {});
    return new Sandbox(id, opts || {});
}

export function count() {
    return parseInt(String(ensure().count()), 10);
}

export function isNativeReady() {
    return native != null;
}

export function load() {
    return native;
}

export default { sandbox, Sandbox, count, load, isNativeReady };
